const STORAGE_KEY = 'todos-javascript';

class Todo {
  constructor(title) {
    this.id = Date.now() + Math.random();
    this.title = title;
    this.completed = false;
  }
}

class TodoModel {
  constructor() {
    this.todos = this.load();
  }

  load() {
    try {
      const data = localStorage.getItem(STORAGE_KEY);
      return data ? JSON.parse(data) : [];
    } catch {
      return [];
    }
  }

  save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(this.todos));
  }

  add(title) {
    const todo = new Todo(title);
    this.todos.push(todo);
    this.save();
    return todo;
  }

  remove(id) {
    this.todos = this.todos.filter(t => t.id !== id);
    this.save();
  }

  toggle(id) {
    const todo = this.todos.find(t => t.id === id);
    if (todo) {
      todo.completed = !todo.completed;
      this.save();
    }
  }

  toggleAll(completed) {
    this.todos.forEach(t => { t.completed = completed; });
    this.save();
  }

  clearCompleted() {
    this.todos = this.todos.filter(t => !t.completed);
    this.save();
  }

  update(id, title) {
    const todo = this.todos.find(t => t.id === id);
    if (todo) {
      todo.title = title;
      this.save();
    }
  }

  getActive() { return this.todos.filter(t => !t.completed); }
  getCompleted() { return this.todos.filter(t => t.completed); }
}

class TodoController {
  constructor(model) {
    this.model = model;
    this.filter = 'all';
    this.editingId = null;
    this.bindEvents();
    this.render();
  }

  bindEvents() {
    document.querySelector('.new-todo').addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        const val = e.target.value.trim();
        if (val) {
          this.model.add(val);
          e.target.value = '';
          this.render();
        }
      }
    });

    document.querySelector('.todo-list').addEventListener('click', (e) => {
      const li = e.target.closest('li');
      if (!li) return;
      const id = Number(li.dataset.id);

      if (e.target.classList.contains('toggle')) {
        this.model.toggle(id);
        this.render();
      }

      if (e.target.classList.contains('destroy')) {
        this.model.remove(id);
        this.render();
      }
    });

    document.querySelector('.todo-list').addEventListener('dblclick', (e) => {
      const label = e.target.closest('label');
      if (!label) return;
      const li = label.closest('li');
      if (!li) return;
      this.editTodo(li);
    });

    document.querySelector('.todo-list').addEventListener('focusout', (e) => {
      if (e.target.classList.contains('edit')) {
        this.commitEdit(e.target);
      }
    });

    document.querySelector('.todo-list').addEventListener('keydown', (e) => {
      if (e.target.classList.contains('edit')) {
        if (e.key === 'Enter') {
          e.target.blur();
        } else if (e.key === 'Escape') {
          this.cancelEdit(e.target);
        }
      }
    });

    document.getElementById('toggle-all').addEventListener('change', (e) => {
      this.model.toggleAll(e.target.checked);
      this.render();
    });

    document.querySelector('.clear-completed').addEventListener('click', () => {
      this.model.clearCompleted();
      this.render();
    });

    window.addEventListener('hashchange', () => {
      this.route();
      this.render();
    });

    this.route();
  }

  route() {
    const hash = window.location.hash;
    if (hash === '#/active') this.filter = 'active';
    else if (hash === '#/completed') this.filter = 'completed';
    else this.filter = 'all';
  }

  editTodo(li) {
    const id = Number(li.dataset.id);
    this.editingId = id;
    li.classList.add('editing');
    const editInput = li.querySelector('.edit');
    editInput.value = li.querySelector('label').textContent;
    editInput.focus();
  }

  commitEdit(input) {
    const li = input.closest('li');
    if (!li) return;
    const id = Number(li.dataset.id);
    const val = input.value.trim();
    if (val) {
      this.model.update(id, val);
    } else {
      this.model.remove(id);
    }
    this.editingId = null;
    this.render();
  }

  cancelEdit(input) {
    const li = input.closest('li');
    if (!li) return;
    li.classList.remove('editing');
    this.editingId = null;
    input.value = li.querySelector('label').textContent;
  }

  render() {
    const todos = this.model.todos;
    const list = document.querySelector('.todo-list');
    const main = document.querySelector('.main');
    const footer = document.querySelector('.footer');
    const countEl = document.querySelector('.todo-count');
    const clearBtn = document.querySelector('.clear-completed');
    const toggleAll = document.getElementById('toggle-all');

    let filtered = todos;
    if (this.filter === 'active') filtered = this.model.getActive();
    else if (this.filter === 'completed') filtered = this.model.getCompleted();

    list.innerHTML = filtered.map(todo => {
      const checked = todo.completed ? 'checked' : '';
      const completedClass = todo.completed ? 'completed' : '';
      const editingClass = this.editingId === todo.id ? 'editing' : '';
      return '<li class="' + completedClass + ' ' + editingClass + '" data-id="' + todo.id + '">' +
        '<div class="view">' +
        '<input class="toggle" type="checkbox" ' + checked + '>' +
        '<label>' + todo.title + '</label>' +
        '<button class="destroy"></button>' +
        '</div>' +
        '<input class="edit" value="' + todo.title + '">' +
        '</li>';
    }).join('');

    const hasTodos = todos.length > 0;
    main.style.display = hasTodos ? '' : 'none';
    footer.style.display = hasTodos ? '' : 'none';

    const activeCount = this.model.getActive().length;
    const word = activeCount === 1 ? 'item' : 'items';
    countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + word + ' left';

    const completedCount = this.model.getCompleted().length;
    clearBtn.style.display = completedCount > 0 ? '' : 'none';

    toggleAll.checked = todos.length > 0 && activeCount === 0;

    const filterLinks = document.querySelectorAll('.filters a');
    filterLinks.forEach(a => {
      a.classList.remove('selected');
      const href = a.getAttribute('href');
      if ((this.filter === 'all' && href === '#/') ||
          (this.filter === 'active' && href === '#/active') ||
          (this.filter === 'completed' && href === '#/completed')) {
        a.classList.add('selected');
      }
    });
  }
}

