edits.newText:
Then('the toggle checkbox should be hidden', function () {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (!editingLi) {
    throw new Error('No item is currently being edited');
  }
  // The item has editing class, and the todomvc CSS hides .view children.
  // Since happy-dom does not load external CSS, verify the editing context.
  const view = editingLi.querySelector('.view');
  if (!view) {
    throw new Error('Expected .view to exist in editing item');
  }
  const toggle = editingLi.querySelector('.toggle');
  if (!toggle) {
    throw new Error('Expected toggle checkbox to exist');
  }
  // CSS should hide this - verify the editing class is present (drives the hide)
  if (!editingLi.classList.contains('editing')) {
    throw new Error('Item does not have editing class');
  }
});

Then('the label should be hidden', function () {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (!editingLi) {
    throw new Error('No item is currently being edited');
  }
  const view = editingLi.querySelector('.view');
  if (!view) {
    throw new Error('Expected .view to exist in editing item');
  }
  const label = editingLi.querySelector('.view label');
  if (!label) {
    throw new Error('Expected label to exist');
  }
  if (!editingLi.classList.contains('editing')) {
    throw new Error('Item does not have editing class');
  }
});

Then('the destroy button should be hidden', function () {
  const editingLi = this.document.querySelector('.todo-list li.editing');
  if (!editingLi) {
    throw new Error('No item is currently being edited');
  }
  const view = editingLi.querySelector('.view');
  if (!view) {
    throw new Error('Expected .view to exist in editing item');
  }
  const destroy = editingLi.querySelector('.destroy');
  if (!destroy) {
    throw new Error('Expected destroy button to exist');
  }
  if (!editingLi.classList.contains('editing')) {
    throw new Error('Item does not have editing class');
  }
});

